export default JSON.parse("{\"id\":\"mindfulness_handout_5\",\"module\":\"Mindfulness\",\"module_category\":\"Mindfulness Skills\",\"item_type\":\"handout\",\"item_number\":\"5\",\"title\":\"Taking Hold of Your Mind: \u201cHow\u201d Skills Nonjudgmentally \\u0003 \u0089 See, but don\u2019t evaluate as good or bad. Just the facts.\",\"source_marker\":\"Mindfulness Handout 5   (Mindfulness Worksheets 2\u20132c, 5\u20135c)\",\"source_pdf\":\"DBT Skills Workbook.pdf\",\"source_pdf_pages\":[84],\"source_book_pages\":[\"60\"],\"related_references\":[\"Mindfulness Worksheets 2\u20132c, 5\u20135c\"],\"is_example\":false,\"fillable_html_created\":false,\"keywords\":[\"Hold\",\"Just\",\"Mind\",\"Nonjudgmentally\",\"Skills\",\"Taking\",\"Your\",\"evaluate\",\"facts\",\"good\"],\"pages\":[{\"pdf_page\":84,\"book_page\":\"60\",\"text\":\"60\\nFrom DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Copyright 2015 by Marsha M. Linehan. Permission\\nto photocopy this handout is granted to purchasers of this book for personal use only (see copyright page for details).\\n\u00ab\\nMindfulness Handout 5   (Mindfulness Worksheets 2\u20132c, 5\u20135c)\\nTaking Hold of Your Mind: \u201cHow\u201d Skills\\nNonjudgmentally\\n\\u0003\\n\u0089 See, but don\u2019t evaluate as good or bad. Just the facts.\\n\\u0003\\n\u0089 Accept each moment like a blanket spread out on the lawn, accepting both the rain and the\\nsun and each leaf that falls upon it.\\n\\u0003\\n\u0089 Acknowledge the difference between the helpful and the harmful, the safe and the dangerous,\\nbut don\u2019t judge them.\\n\\u0003\\n\u0089 Acknowledge your values, your wishes, your emotional reactions, but don\u2019t judge them.\\n\\u0003\\n\u0089 When you find yourself judging, don\u2019t judge your judging.\\nOne-Mindfully\\n\\u0003\\n\u0089 Rivet yourself to now. Be completely present to this one moment.\\n\\u0003\\n\u0089 Do one thing at a time. Notice the desire to be half-present, to be somewhere else, to go\\nsomewhere else in your mind, to do something else, to multitask\u2014and then come back to one\\nthing at a time.\\n\u2022\u2022 When you are eating, eat.\\n\u2022\u2022 When you are walking, walk.\\n\u2022\u2022 When you are worrying, worry.\\n\u2022\u2022 When you are planning, plan.\\n\u2022\u2022 When you are remembering, remember.\\n\\u0003\\n\u0089 Let go of distractions. If other actions, or other thoughts, or strong feelings distract you, go\\nback to what you are doing\u2014again, and again, and again.\\n\\u0003\\n\u0089 Concentrate your mind. If you find you are doing two things at once, stop\u2014go back to one\\nthing at a time (the opposite of multitasking!).\\nEffectively\\n\\u0003\\n\u0089 Be mindful of your goals in the situation, and do what is necessary to achieve them.\\n\\u0003\\n\u0089 Focus on what works. (Don\u2019t let emotion mind get in the way of being effective.)\\n\\u0003\\n\u0089 Play by the rules.\\n\\u0003\\n\u0089 Act as skillfully as you can. Do what is needed for the situation you are in\u2014not the situation\\nyou wish you were in; not the one that is fair; not the one that is more comfortable.\\n\\u0003\\n\u0089 Let go of willfulness and sitting on your hands.\"}],\"full_text\":\"\u00ab\\nMindfulness Handout 5   (Mindfulness Worksheets 2\u20132c, 5\u20135c)\\nTaking Hold of Your Mind: \u201cHow\u201d Skills\\nNonjudgmentally\\n\\u0003\\n\u0089 See, but don\u2019t evaluate as good or bad. Just the facts.\\n\\u0003\\n\u0089 Accept each moment like a blanket spread out on the lawn, accepting both the rain and the\\nsun and each leaf that falls upon it.\\n\\u0003\\n\u0089 Acknowledge the difference between the helpful and the harmful, the safe and the dangerous,\\nbut don\u2019t judge them.\\n\\u0003\\n\u0089 Acknowledge your values, your wishes, your emotional reactions, but don\u2019t judge them.\\n\\u0003\\n\u0089 When you find yourself judging, don\u2019t judge your judging.\\nOne-Mindfully\\n\\u0003\\n\u0089 Rivet yourself to now. Be completely present to this one moment.\\n\\u0003\\n\u0089 Do one thing at a time. Notice the desire to be half-present, to be somewhere else, to go\\nsomewhere else in your mind, to do something else, to multitask\u2014and then come back to one\\nthing at a time.\\n\u2022\u2022 When you are eating, eat.\\n\u2022\u2022 When you are walking, walk.\\n\u2022\u2022 When you are worrying, worry.\\n\u2022\u2022 When you are planning, plan.\\n\u2022\u2022 When you are remembering, remember.\\n\\u0003\\n\u0089 Let go of distractions. If other actions, or other thoughts, or strong feelings distract you, go\\nback to what you are doing\u2014again, and again, and again.\\n\\u0003\\n\u0089 Concentrate your mind. If you find you are doing two things at once, stop\u2014go back to one\\nthing at a time (the opposite of multitasking!).\\nEffectively\\n\\u0003\\n\u0089 Be mindful of your goals in the situation, and do what is necessary to achieve them.\\n\\u0003\\n\u0089 Focus on what works. (Don\u2019t let emotion mind get in the way of being effective.)\\n\\u0003\\n\u0089 Play by the rules.\\n\\u0003\\n\u0089 Act as skillfully as you can. Do what is needed for the situation you are in\u2014not the situation\\nyou wish you were in; not the one that is fair; not the one that is more comfortable.\\n\\u0003\\n\u0089 Let go of willfulness and sitting on your hands.\",\"copyright_notice\":\"Extracted from user-provided PDF: DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Respect source copyright and purchaser-use limits.\",\"created_at\":\"2026-06-25T17:33:54\",\"json_path\":\"json/items/mindfulness/handouts/mindfulness_handout_5_taking_hold_of_your_mind_how_skills_nonjudgmentally_see_but_don_t_eval.json\",\"ourspace_shared_life_filter\":{\"revision_id\":\"ourspace_shared_life_filter_v1\",\"title\":\"Taking Hold of Your Mind: \u201cHow\u201d Skills Nonjudgmentally \\u0003 \u0089 See, but don\u2019t evaluate as good or bad. Just the facts.\",\"domain\":\"mindfulness\",\"item_type\":\"handout\",\"shared_facing_summary\":\"Mindfulness is allowed to be tiny, sensory-safe, and done from bed or wheelchair. Noticing without judging counts even when the day is messy.\",\"tiny_steps\":[\"Notice one body signal.\",\"Name one feeling or need.\",\"Find one neutral thing in the room.\",\"Return to the next safe action.\"],\"flare_day_versions\":{\"minimum\":\"One breath, one label, one safe message, or one checkbox.\",\"medium\":\"Two to five minutes with everything reachable from bed/chair.\",\"full\":\"Use the original worksheet/handout when both bodies and brains have capacity.\"},\"accessibility_modifications\":[\"Use eyes-open grounding if closing eyes feels unsafe.\",\"Use quiet, low-scent, low-touch options for MCAS, trauma, and sensory overload.\",\"No posture requirement; lying down or supported sitting is valid.\"],\"relationship_and_caregiver_notes\":[\"William's needs and Jasper's capacity both count.\",\"Ask before helping; ask before escalating; name the smallest next step.\",\"Pause means pause, not abandonment. I am coming back. I care about us. I need a smaller next step.\",\"What is needed, what capacity exists, what can be smaller, and what can wait?\"],\"identity_and_trauma_filter\":[\"Use William's masculine language and Jasper's they/them language.\",\"Use consent-based, non-shaming, body-neutral language unless a person has explicitly chosen a term.\",\"Do not turn symptoms, dysphoria, trauma responses, clutter, fatigue, or emotional intensity into moral failure.\"],\"avoid_or_adjust\":[\"Do not force stillness when it increases pain, panic, dysphoria, or trauma activation.\"],\"suggested_cadence\":[\"daily_optional\",\"flare_day_as_needed\"],\"app_tags\":[\"adhd_friendly\",\"disability_first\",\"mindfulness\",\"shared\",\"tiny_steps\",\"trauma_informed\"]},\"ourspace_shared_revision_metadata\":{\"source_path\":\"DBT+ADHD Skill Files/02_DBT_Mindfulness/handouts/json/mindfulness_handout_5_taking_hold_of_your_mind_how_skills_nonjudgmentally_see_but_don_t_eval.json\",\"shared_output_path\":\"shared/02_dbt_mindfulness/handouts_json/mindfulness_handout_5_taking_hold_of_your_mind_how_skills_nonjudgmentally_76ac5dce.json\",\"revised_at_utc\":\"2026-06-26T00:24:16Z\",\"copyright_note\":\"Extracted from user-provided PDF: DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Respect source copyright and purchaser-use limits.\"},\"shared_json_path\":\"shared/02_dbt_mindfulness/handouts_json/mindfulness_handout_5_taking_hold_of_your_mind_how_skills_nonjudgmentally_76ac5dce.json\"}");
